import{_ as o,o as s,c as n,ag as r}from"./chunks/framework.KxDd3USm.js";const p=JSON.parse('{"title":"03.3 模块化设计：内聚、耦合与模块原则 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/03-模块化设计.md","filePath":"03-软件工程基础/03-模块化设计.md"}'),g={name:"03-软件工程基础/03-模块化设计.md"};function d(a,t,u,l,e,q){return s(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="_03-3-模块化设计-内聚、耦合与模块原则-★★★" tabindex="-1">03.3 模块化设计：内聚、耦合与模块原则 ★★★ <a class="header-anchor" href="#_03-3-模块化设计-内聚、耦合与模块原则-★★★" aria-label="Permalink to &quot;03.3 模块化设计：内聚、耦合与模块原则 ★★★&quot;">​</a></h1><h3 id="_3-0-为什么要-高内聚、低耦合" tabindex="-1">3.0 为什么要&quot;高内聚、低耦合&quot; <a class="header-anchor" href="#_3-0-为什么要-高内聚、低耦合" aria-label="Permalink to &quot;3.0 为什么要&quot;高内聚、低耦合&quot;&quot;">​</a></h3><p>软件要拆成模块，拆法有好坏：一个模块内部干的事<strong>越相关</strong>（内聚越高），越容易看懂、改起来越不容易牵连别处；模块之间<strong>越独立</strong>（耦合越低），一个模块改动对别的影响越小。&quot;高内聚、低耦合&quot;就是这两条经验的一句话版。<strong>内聚看模块内部，耦合看模块之间</strong>——先分清这个方向再背排序。</p><h3 id="_3-1-模块设计的六条原则-真题的-下列错误的是-常客" tabindex="-1">3.1 模块设计的六条原则（真题的&quot;下列错误的是&quot;常客） <a class="header-anchor" href="#_3-1-模块设计的六条原则-真题的-下列错误的是-常客" aria-label="Permalink to &quot;3.1 模块设计的六条原则（真题的&quot;下列错误的是&quot;常客）&quot;">​</a></h3><p>内聚与耦合只回答了&quot;模块怎么拆才算好&quot;里的一个维度。完整的模块设计原则是<strong>六条</strong>，其中三条专考：</p><p><strong>① 保持模块的大小适中</strong></p><ul><li>过大：内部可能揉进不同类型的功能，需要进一步划分，尽量让各模块功能单一；</li><li>过小：系统复杂度反而增加，<strong>模块之间的调用过于频繁，降低了模块的独立性</strong>。</li><li><strong>结论：模块规模不是越小越好</strong>——&quot;模块规模越小越好&quot;是真题的固定错项。</li></ul><p><strong>② 深度、宽度适中</strong></p><ul><li><strong>深度</strong> = 软件结构中模块的<strong>层数</strong>。层数过多 → 说明有些模块设计得过于简单，应考虑<strong>合并</strong>。</li><li><strong>宽度</strong> = 软件结构中<strong>同一层次上模块总数的最大值</strong>。影响宽度最大的因素是<strong>模块的扇出</strong>。宽度越大系统越复杂。</li></ul><p><strong>③ 扇入、扇出系数要合理</strong></p><ul><li><strong>扇入</strong> = 该模块的<strong>直接上级模块的个数</strong>（有多少个模块调用它）；</li><li><strong>扇出</strong> = 该模块的<strong>直属下级模块的个数</strong>（它调用了多少个模块）；</li><li>原则是&quot;<strong>多扇入、少扇出</strong>&quot;：扇入大 = 复用性好（很多模块都用它，改好一处全都受益）；扇出小 = 该模块自身比较独立、不牵动一大片。经典的错项写法是反过来写&quot;多扇出、少扇入&quot;。</li></ul><p><strong>④ 模块的作用域应该在控制域之内</strong>（最绕、最爱考）</p><ul><li><strong>控制域</strong> = 这个模块<strong>本身</strong>以及所有<strong>直接或间接从属于它</strong>的模块的集合；</li><li><strong>作用域</strong> = 受该模块<strong>内一个判定所影响</strong>的所有模块的集合；</li><li>要求：<strong>判定的影响范围必须落在该模块能控制的范围内</strong>。</li></ul><p><strong>违反时的样子与改法</strong>（一眼看懂）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        M（主控）</span></span>
<span class="line"><span>       /  \\</span></span>
<span class="line"><span>      A    B        判定 P 写在 A 里面，</span></span>
<span class="line"><span>     (P)             但 P 的结果要影响兄弟模块 B</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A 的控制域 = {A}   ← A 没有下级，管不到 B</span></span>
<span class="line"><span>A 的作用域 = {B}   ← P 影响的是 B</span></span>
<span class="line"><span>{B} ⊄ {A}  → 违反！A 只能在算完之后把结果当参数往外传，耦合被迫升高</span></span></code></pre></div><p>改法二选一：<strong>把判定 P 上移到 M</strong>（此时 M 的控制域 = {M, A, B} ⊇ {B} ✓）；或者<strong>把被影响的模块 B 下移到 A 之下</strong>。</p><p><strong>⑤ 功能应该是可预测的</strong> 模块的功能要单一、结果要可预期。反例：一个模块的输出取决于某个全局变量的当前值，同样的入参可能返回不同结果，调用者无法预知——这就是&quot;功能不可预测&quot;，属设计缺陷。<strong>&quot;模块的功能应该是不可预测的&quot;是真题的固定错项。</strong></p><p><strong>⑥ 高内聚、低耦合</strong>：见 3.2、3.3。</p><h3 id="_3-2-内聚七级-从低到高-必须背顺序" tabindex="-1">3.2 内聚七级（从低到高，必须背顺序） <a class="header-anchor" href="#_3-2-内聚七级-从低到高-必须背顺序" aria-label="Permalink to &quot;3.2 内聚七级（从低到高，必须背顺序）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>名称</th><th>含义</th><th>一句话识别</th></tr></thead><tbody><tr><td>1</td><td><strong>偶然内聚</strong>（巧合内聚）</td><td>动作之间毫无关系，凑在一起（如&quot;为了省事把几个无关函数塞一个模块&quot;）</td><td>&quot;没什么关系，硬凑&quot;</td></tr><tr><td>2</td><td><strong>逻辑内聚</strong></td><td>逻辑上<strong>相似</strong>但功能用途无关（如一个模块按参数分别执行打印输入/打印输出）</td><td>&quot;相似但无关&quot;</td></tr><tr><td>3</td><td><strong>时间内聚</strong>（瞬时内聚）</td><td>动作无关，但必须在<strong>同一时间</strong>（同一时间间隔内）执行（如初始化模块）</td><td>&quot;同一时间&quot;</td></tr><tr><td>4</td><td><strong>过程内聚</strong></td><td>动作关系不大，但必须<strong>按特定次序</strong>执行</td><td>&quot;按次序但无实质关系&quot;</td></tr><tr><td>5</td><td><strong>通信内聚</strong></td><td>各动作对<strong>同一数据</strong>进行操作（如对同一份数据先读后存再打印）</td><td>&quot;围绕同一数据&quot;</td></tr><tr><td>6</td><td><strong>顺序内聚</strong></td><td>前一个动作的<strong>输出</strong>正好是后一个动作的<strong>输入</strong>（必须顺序执行）</td><td>&quot;接力棒&quot;</td></tr><tr><td>7</td><td><strong>功能内聚</strong></td><td>所有部分合起来完成<strong>单一功能</strong>（如计算利息），协同工作缺一不可</td><td>&quot;就是一个功能&quot;</td></tr></tbody></table><h3 id="_3-3-耦合七级-从高到低-必须背顺序" tabindex="-1">3.3 耦合七级（从高到低，必须背顺序） <a class="header-anchor" href="#_3-3-耦合七级-从高到低-必须背顺序" aria-label="Permalink to &quot;3.3 耦合七级（从高到低，必须背顺序）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>名称</th><th>含义</th><th>一句话识别</th></tr></thead><tbody><tr><td>1</td><td><strong>内容耦合</strong></td><td>一个模块直接访问另一个模块的<strong>内部</strong>数据或代码；或不经正常入口转入内部；或两块代码重叠；或一个模块有多个入口</td><td>&quot;掀开别人内脏&quot;</td></tr><tr><td>2</td><td><strong>公共耦合</strong></td><td>多个模块通过<strong>同一公共数据环境</strong>（全局数据结构，如一个大数组、一个公共文件）传递信息</td><td>&quot;共用一个大仓库&quot;</td></tr><tr><td>3</td><td><strong>外部耦合</strong></td><td>多个模块访问<strong>同一全局简单变量</strong>（不是数据结构），且不是通过参数表传递</td><td>&quot;共用一个全局变量&quot;</td></tr><tr><td>4</td><td><strong>控制耦合</strong></td><td>传递的信息中含<strong>控制信号</strong>（如开关标志决定对方走哪个分支）</td><td>&quot;传的是命令不是数据&quot;</td></tr><tr><td>5</td><td><strong>标记耦合</strong></td><td>通过参数表传递<strong>记录信息/数据结构</strong>（而非简单变量）</td><td>&quot;传一整条记录&quot;</td></tr><tr><td>6</td><td><strong>数据耦合</strong></td><td>通过参数表传递<strong>简单数据</strong></td><td>&quot;传一个数&quot;</td></tr><tr><td>7</td><td><strong>非直接耦合</strong></td><td>两模块之间<strong>没有直接关系</strong>，联系完全通过<strong>主模块的控制和调用</strong>实现</td><td>&quot;各干各的，上级牵线&quot;</td></tr></tbody></table><h3 id="_3-4-反例演示-最易混四组" tabindex="-1">3.4 反例演示（最易混四组） <a class="header-anchor" href="#_3-4-反例演示-最易混四组" aria-label="Permalink to &quot;3.4 反例演示（最易混四组）&quot;">​</a></h3><ol><li><strong>逻辑内聚 vs 偶然内聚</strong>：动作之间&quot;有点相似&quot;（都跟打印/输入输出沾边）→ 逻辑内聚；&quot;完全没关系&quot;→ 偶然内聚。判别标准是<strong>相似性</strong>是否存在。</li><li><strong>时间内聚 vs 过程内聚</strong>：都是&quot;关系不大硬放一起&quot;，区别在<strong>约束是&quot;同时&quot;还是&quot;先后&quot;</strong>——初始化必须一起做 = 时间；必须按某次序执行 = 过程。</li><li><strong>公共耦合 vs 外部耦合</strong>：共用的是<strong>数据结构</strong>（一整个数组/记录/文件）→ 公共耦合；只是<strong>简单变量</strong>（一个全局计数器）→ 外部耦合。</li><li><strong>标记耦合 vs 数据耦合</strong>：参数传的是<strong>一条记录/结构</strong>（整个学生信息）→ 标记耦合；只是<strong>一个简单变量</strong>（学号这一个数）→ 数据耦合。</li></ol><p><strong>再强调一处易错</strong>：耦合的<strong>数据类</strong>三项（控制 &gt; 标记 &gt; 数据）排序时，<strong>&quot;传记录&quot;比&quot;传简单变量&quot;耦合高</strong>——因为在传递的内容里，前者包含了后者的全部信息，改记录结构会牵连更多模块。</p><p><strong>应试动作</strong>：① 两个排序必须能默写——内聚从&quot;凑（偶然）&quot;到&quot;专（功能）&quot;，耦合从&quot;掀内脏（内容）&quot;到&quot;不认识（非直接）&quot;；② 做题先抓题干关键词（同一时间/同一数据/接力/命令/记录/变量/全局）对号入座；③ 模块原则题抓三个&quot;反向错项&quot;——&quot;越小越好&quot;&quot;多扇出少扇入&quot;&quot;功能不可预测&quot;，见到就选它错。</p>`,26)])])}const h=o(g,[["render",d]]);export{p as __pageData,h as default};
